{
  "name": "opencode-mem0",
  "version": "2.24.1",
  "description": "OpenCode plugin that gives coding agents persistent memory using local vector database",
  "type": "module",
  "main": "dist/plugin.js",
  "bin": {
    "opencode-mem0": "dist/cli.js"
  },
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/plugin.js",
      "types": "./dist/index.d.ts"
    },
    "./server": {
      "import": "./dist/plugin.js",
      "types": "./dist/index.d.ts"
    },
    "./tags": {
      "types": "./dist/services/tags.d.ts",
      "import": "./dist/services/tags.js"
    }
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:coverage": "vitest run --coverage",
    "format": "prettier --write \"src/**/*.{ts,js,css,html}\"",
    "format:check": "prettier --check \"src/**/*.{ts,js,css,html}\"",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "vector-database",
    "ai",
    "coding-agent",
    "local",
    "standalone"
  ],
  "author": "ZeR020",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ZeR020/opencode-mem0.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "bun": ">=1.0.0",
    "node": ">=20.0.0"
  },
  "bugs": {
    "url": "https://github.com/ZeR020/opencode-mem0/issues"
  },
  "homepage": "https://github.com/ZeR020/opencode-mem0#readme",
  "dependencies": {
    "@ai-sdk/anthropic": "^4.0.5",
    "@ai-sdk/openai": "^4.0.5",
    "@huggingface/transformers": "^4.2.0",
    "@opencode-ai/plugin": "^1.14.31",
    "@opencode-ai/sdk": "^1.14.31",
    "ai": "^7.0.4",
    "franc-min": "^6.2.0",
    "jsonc-parser": "^3.3.1",
    "usearch": "^2.25.1",
    "zod": "^4.4.1"
  },
  "optionalDependencies": {
    "better-sqlite3": "^13.0.2"
  },
  "devDependencies": {
    "@types/better-sqlite3": "^9.6.0",
    "@types/bun": "^1.3.13",
    "@vitest/coverage-v8": "^4.1.9",
    "husky": "^9.1.7",
    "lint-staged": "^17.0.8",
    "prettier": "^3.8.3",
    "typescript": "^7.0.2",
    "vitest": "^4.1.9"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "event"
    ]
  },
  "files": [
    "dist"
  ],
  "overrides": {
    "protobufjs": "^7.6.4",
    "vite": "^7.3.6",
    "esbuild": "^0.28.1",
    "ws": ">=8.20.1",
    "yaml": "^2.8.3",
    "uuid": "^14.0.0"
  },
  "lint-staged": {
    "*.{ts,tsx,js,jsx,css,html,json,md}": [
      "prettier --write"
    ]
  }
}
